}

{name, sex, age: [a, b, c]} = obj;
console.log(c);

对象嵌套对象属性名重复时解构
var obj = {
    name: 'chris',
    sex: 'male',
    age: 26,
    son: {
        name: '大熊',
        sex: 'male',
        age: 1
        }
    };
    //赋值解构
var {name: fathername, son: {name, sex, age}} = obj;
console.log(fathername); //chris
console.log(name);

变量值互换
var a = 1,
    b = 2;

var [b, a] = [a, b];
console.log(a + ' ' + b);

字符串解构
var str = 'hello';
var [a, b, c, d, e] = str;
console.log(a + ' '  + b);//a b
``` 

拓展运算符：把数组或对象展开成由逗号隔开的值

```
深拷贝
var a = [1, 2];
var b = a;
var c = [...a];
console.log(a === b);//true
console.log(a === c);//false

字符串转数组
var str = 'hello';
var exstr = [...str];
console.log(exstr);//['h', 'e', 'l', 'l', 'o']
```

